template:
module vector_not4(input [3:0] in, output [3:0] out);
  // Your code here
  // Use bitwise NOT operator: ~
  // Example: assign out = ~in;
endmodule

testbench:
`timescale 1ns/1ps
module tb();
    reg [3:0] in;
    wire [3:0] out;
    integer passed_tests = 0;
    integer total_tests = 0;

    vector_not4 dut (.in(in), .out(out));

    initial begin
        $display("Testing 4-bit Vector NOT...");

        // Test case 1: All zeros
        in = 4'b0000; #10;
        total_tests = total_tests + 1;
        if (out !== 4'b1111) $display("FAIL: in=%b, out=%b (expected 1111)", in, out); else passed_tests = passed_tests + 1;

        // Test case 2: 1010
        in = 4'b1010; #10;
        total_tests = total_tests + 1;
        if (out !== 4'b0101) $display("FAIL: in=%b, out=%b (expected 0101)", in, out); else passed_tests = passed_tests + 1;

        // Test case 3: All ones
        in = 4'b1111; #10;
        total_tests = total_tests + 1;
        if (out !== 4'b0000) $display("FAIL: in=%b, out=%b (expected 0000)", in, out); else passed_tests = passed_tests + 1;

        // Test case 4: 0110
        in = 4'b0110; #10;
        total_tests = total_tests + 1;
        if (out !== 4'b1001) $display("FAIL: in=%b, out=%b (expected 1001)", in, out); else passed_tests = passed_tests + 1;

        // Random test
        in = 4'b1100; #10;
        total_tests = total_tests + 1;
        if (out !== 4'b0011) $display("FAIL: in=%b, out=%b (expected 0011)", in, out); else passed_tests = passed_tests + 1;

        if (passed_tests == total_tests) begin
            $display("PASS: All %0d tests passed", total_tests);
        end else begin
            $display("FAIL: %0d/%0d tests passed", passed_tests, total_tests);
        end
        $finish;
    end
endmodule

