module top_module(input a, b, output out);
  // Your code here
  // Use AND operator: &
  // Example: assign out = a & b;
endmodule

testbench:
`timescale 1ns/1ps
module tb();
    reg a, b;
    wire out;
    integer passed_tests = 0;
    integer total_tests = 0;

    top_module dut (.a(a), .b(b), .out(out));

    initial begin
        $display("Testing AND gate...");

        a=0; b=0; #10;
        total_tests = total_tests + 1;
        if (out !== 1'b0) $display("FAIL 00"); else passed_tests = passed_tests + 1;

        a=0; b=1; #10;
        total_tests = total_tests + 1;
        if (out !== 1'b0) $display("FAIL 01"); else passed_tests = passed_tests + 1;

        a=1; b=0; #10;
        total_tests = total_tests + 1;
        if (out !== 1'b0) $display("FAIL 10"); else passed_tests = passed_tests + 1;

        a=1; b=1; #10;
        total_tests = total_tests + 1;
        if (out !== 1'b1) $display("FAIL 11"); else passed_tests = passed_tests + 1;

        if (passed_tests == total_tests) $display("PASS"); else $display("FAIL");
        $finish;
    end
endmodule

