template:
module top_module(input clk, input d, output reg q);
  // Your code here
  // Use always @(posedge clk) block
  // Example: always @(posedge clk) q <= d;
endmodule

testbench:
`timescale 1ns/1ps
module tb();
    reg clk=0, d;
    wire q;
    integer passed_tests = 0;
    integer total_tests = 0;

    top_module dut (.clk(clk), .d(d), .q(q));
    always #5 clk = ~clk;

    initial begin
        $display("Testing D Flip-Flop...");

        d=0; #10;
        total_tests = total_tests + 1;
        if (q !== 1'b0) $display("FAIL 1"); else passed_tests = passed_tests + 1;

        d=1; #10;
        total_tests = total_tests + 1;
        if (q !== 1'b1) $display("FAIL 2"); else passed_tests = passed_tests + 1;

        d=0; #10;
        total_tests = total_tests + 1;
        if (q !== 1'b0) $display("FAIL 3"); else passed_tests = passed_tests + 1;

        if (passed_tests == total_tests) $display("PASS"); else $display("FAIL");
        $finish;
    end
endmodule

template:
module top_module(input a, b, output sum, carry);
  // Your code here
  // Sum = a XOR b
  // Carry = a AND b
endmodule

testbench:
`timescale 1ns/1ps
module tb();
    reg a, b;
    wire sum, carry;
    integer passed_tests = 0;
    integer total_tests = 0;

    top_module dut (.a(a), .b(b), .sum(sum), .carry(carry));

    initial begin
        $display("Testing Half Adder...");

        a=0; b=0; #10;
        total_tests = total_tests + 1;
        if (!(sum===0 && carry===0)) $display("FAIL 00"); else passed_tests = passed_tests + 1;

        a=0; b=1; #10;
        total_tests = total_tests + 1;
        if (!(sum===1 && carry===0)) $display("FAIL 01"); else passed_tests = passed_tests + 1;

        a=1; b=0; #10;
        total_tests = total_tests + 1;
        if (!(sum===1 && carry===0)) $display("FAIL 10"); else passed_tests = passed_tests + 1;

        a=1; b=1; #10;
        total_tests = total_tests + 1;
        if (!(sum===0 && carry===1)) $display("FAIL 11"); else passed_tests = passed_tests + 1;

        if (passed_tests == total_tests) $display("PASS"); else $display("FAIL");
        $finish;
    end
endmodule
